import unittest
from preview import prefix

class Prefix(unittest.TestCase):
    def test_utf8(self):
        for budget, expected in [(0,''),(1,'A'),(2,'A'),(3,'Aé'),(4,'Aé'),(6,'Aé'),(7,'Aé🚲'),(8,'Aé🚲Z'),(100,'Aé🚲Z')]:
            self.assertEqual(prefix('Aé🚲Z', budget), expected)
        self.assertEqual(prefix('界a', 2), '')
        self.assertEqual(prefix('e\u0301x', 2), 'e')
        self.assertEqual(prefix('', 1), '')
    def test_negative(self):
        with self.assertRaises(ValueError): prefix('abc', -1)

if __name__ == '__main__':
    unittest.main()

